import{_ as a,a as t,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 16 The modern city","description":"学习 so…that 与 such…that 的结果表达，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 16 The modern city","description":"学习 so…that 与 such…that 的结果表达，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 so…that 与 such…that 的结果表达，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 15 Secrecy in industry","link":"/life/english/new-concept/book-4/unit-02/lesson-015"},"next":{"text":"第四册：流利英语 · Lesson 17 A man-made disease","link":"/life/english/new-concept/book-4/unit-03/lesson-017"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 15 Secrecy in industry","link":"/life/english/new-concept/book-4/unit-02/lesson-015"},"next":{"text":"第四册：流利英语 · Lesson 17 A man-made disease","link":"/life/english/new-concept/book-4/unit-03/lesson-017"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-016.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-016.md"}'),n={name:"life/english/new-concept/book-4/unit-02/lesson-016.md"};function i(r,e,l,h,c,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第四册-流利英语-·-lesson-16-the-modern-city" tabindex="-1">第四册：流利英语 · Lesson 16 The modern city <a class="header-anchor" href="#第四册-流利英语-·-lesson-16-the-modern-city" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 16 The modern city&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过城市规模、交通和公共空间的关系学习阅读抽象描述。将笼统的“城市令人疏离”转成可讨论的具体设计问题，例如步行距离、交往机会和服务可达性。练习识别结果结构，同时检查作者是否提供了足够依据支持其因果判断和概括范围。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>density</td><td>/ˈdensəti/</td><td>n.</td><td>密度</td><td>population density</td></tr><tr><td>pedestrian</td><td>/pəˈdestriən/</td><td>n.</td><td>行人</td><td>a pedestrian crossing</td></tr><tr><td>isolation</td><td>/ˌaɪsəˈleɪʃən/</td><td>n.</td><td>隔离感</td><td>social isolation</td></tr><tr><td>accessible</td><td>/əkˈsesəbəl/</td><td>adj.</td><td>易到达的</td><td>accessible public spaces</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>within walking distance — 在步行可达范围内</li><li>make room for — 为某物腾出空间</li></ul><h2 id="语法讲解-so-that-与-such-that-的结果表达" tabindex="-1">语法讲解：so…that 与 such…that 的结果表达 <a class="header-anchor" href="#语法讲解-so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;语法讲解：so…that 与 such…that 的结果表达&quot;">​</a></h2><p>so 后接形容词或副词，such 后接名词短语：so crowded that… 与 such a crowded street that…。so many/few 加可数复数，so much/little 加不可数名词，是需要单独记忆的数量结构。that 从句描述程度造成的结果，与表示目的的 so that 不同。阅读时要判断句中是否先有程度词；语法上写出结果也不能代替真实的因果证据。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The crossing was so far away that several residents asked for a nearer one.</p></blockquote><p>人行横道太远，以至于几位居民要求设置一个更近的。</p><p>so 修饰形容词短语 far away；that 从句给出结果；one 指 crossing。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>such far away 结构错误；没有名词短语时应使用 so far away。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读时重读 so far，再在 that 前小停顿；比较 so far that 与 so that 的节奏，辨认程度结果和目的。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The bus stop is so far from the library that some visitors drive instead. A nearer stop could make the library easier to reach. The council should also ask residents about their routes.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句描述一个街区步行问题，包含程度结果结构和一条改善建议。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>先给具体空间问题，再提出可能改善和信息收集，不把单一观察泛化为所有城市。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：It was ___ a narrow pavement that two people could not pass.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> such</p><p><strong>解析：</strong> 后面是 a narrow pavement 名词短语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中的 one 代替什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> crossing</p><p><strong>解析：</strong> 避免重复同类可数名词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>选择：so many traffic / so much traffic。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> so much traffic</p><p><strong>解析：</strong> traffic 通常为不可数名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：so…that 与 such…that 的结果表达。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-017">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",i]]);export{u as __pageData,b as default};
